<?php require_once __DIR__.'/../includes/auth.php';require_role(['student']);$errors=[];$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)($_POST['report_type']??'');$name=trim((string)($_POST['item_name']??''));$desc=trim((string)($_POST['description']??''));$loc=trim((string)($_POST['location']??''));$date=(string)($_POST['date_occurred']??'');$cat=(int)($_POST['category_id']??0);if(!in_array($type,['lost','found'],true))$errors[]='Choose lost or found.';if($name===''||mb_strlen($name)>120)$errors[]='Item name is required (maximum 120 characters).';if($desc===''||mb_strlen($desc)>2000)$errors[]='Description is required (maximum 2,000 characters).';if($loc===''||mb_strlen($loc)>200)$errors[]='Enter a location (maximum 200 characters).';$d=DateTime::createFromFormat('Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)$errors[]='Choose a valid date.';if(!$cat)$errors[]='Choose a category.';if(!$errors){$s=$pdo->prepare('INSERT INTO item_reports(user_id,category_id,report_type,item_name,description,location,date_occurred) VALUES(?,?,?,?,?,?,?)');$s->execute([current_user()['id'],$cat,$type,$name,$desc,$loc,$date]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO status_history(item_report_id,changed_by,old_status,new_status,notes) VALUES(?,?,?,?,?)')->execute([$id,current_user()['id'],null,'open','Report created']);flash('success','Your report has been submitted.');redirect('student/my-reports.php');}}$pageTitle='Report an item';require __DIR__.'/../includes/header.php';?><section class="form-wrap wide"><h1>Report a lost or found item</h1><p>Do not include passwords, private IDs, or sensitive personal information in the public description.</p><?php foreach($errors as $er):?><div class="alert error"><?=e($er)?></div><?php endforeach;?><form method="post" class="panel"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Report type<select name="report_type" required><option value="">Choose…</option><option value="lost">I lost an item</option><option value="found">I found an item</option></select></label><label>Category<select name="category_id" required><option value="">Choose…</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label></div><label>Item name<input name="item_name" maxlength="120" required></label><label>Description<textarea name="description" rows="4" maxlength="2000" required></textarea></label><div class="form-grid"><label>Location<input name="location" maxlength="200" required placeholder="e.g. Library, 2nd floor"></label><label>Date lost/found<input type="date" name="date_occurred" required max="<?=date('Y-m-d')?>"></label></div><button class="btn primary">Submit report</button></form></section><?php require __DIR__.'/../includes/footer.php';?>
